171	    const ids: Record<FieldKey, string> = {
172	      clientName: `${prefix}-client`,
173	      matterName: `${prefix}-matter`,
174	      matterType: `${prefix}-type`,
175	      opened: `${prefix}-opened`,
176	      conflictCheck: `${prefix}-conflict-check`,
177	    };
178	    const [values, setValues] = React.useState<Values>(EMPTY);
179	    const [submitted, setSubmitted] = React.useState(false);
180	    const [attempt, setAttempt] = React.useState(0);
181	    // What the summary lists: the errors as of the last submit. It's a live region, so it doesn't
182	    // change while people type; the fields do.
183	    const [summaryErrors, setSummaryErrors] = React.useState<FieldError[]>([]);
184	    const [saving, setSaving] = React.useState(false);
185	    const summary = React.useRef<HTMLDivElement>(null);
186	
187	    // After a failed submit, each field's error follows its value, so it clears as soon as it's fixed.
188	    const errors = submitted ? check(values) : [];
189	    const errorFor = (key: FieldKey) => errors.find((error) => error.key === key)?.message;
190	    const set = <K extends FieldKey>(key: K, value: Values[K]) => setValues((current) => ({ ...current, [key]: value }));
191	
192	    // Move focus to the summary after each failed submit, so it's read out and people start there.
193	    React.useEffect(() => {
194	      if (attempt > 0) summary.current?.focus();
195	    }, [attempt]);
196	
197	    const reset = () => {
198	      setValues(EMPTY);
199	      setSubmitted(false);
200	      setAttempt(0);
201	      setSummaryErrors([]);
202	    };
203	
204	    const submit = (event: React.FormEvent) => {
205	      event.preventDefault();
206	      if (saving) return;
207	      setSubmitted(true);
208	      const failed = check(values);
209	      setSummaryErrors(failed);
210	      if (failed.length > 0) {
211	        setAttempt((count) => count + 1);
212	        return;
213	      }
214	      setSaving(true);
215	      window.setTimeout(() => {
216	        setSaving(false);
217	        reset();
218	        toast.success('Matter created', { description: `${values.matterName} was opened for ${values.clientName}.` });
219	      }, 1500);
220	    };
