  name: string;
  email: string;
  /** Whether the contact gets updates by email. Saved with the form. */
  emailUpdates: boolean;
}

export interface NewContactFormProps {
  /** Called with the contact once it passes the checks. Return a promise to show the Save button busy while it saves. */
  onSave: (contact: NewContact) => void | Promise<void>;
  /** Called when someone cancels. The Cancel button shows only when this is set. */
  onCancel?: () => void;
}

type FieldKey = 'name' | 'email';
interface FieldError {
  key: FieldKey;
  label: string;
  message: string;
}

const EMPTY: NewContact = { name: '', email: '', emailUpdates: false };

// Deliberately loose: one @, something on each side, a dot in the domain. The server has the last word.
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function check({ name, email }: NewContact): FieldError[] {
  const errors: FieldError[] = [];
  if (!name.trim()) errors.push({ key: 'name', label: 'Name', message: "Enter the contact's name." });
  if (!email.trim()) errors.push({ key: 'email', label: 'Email', message: "Enter the contact's email address." });
  else if (!EMAIL_PATTERN.test(email.trim()))
    errors.push({ key: 'email', label: 'Email', message: 'Enter an email address with an @ and a domain, such as jordan.lee@example.com.' });
  return errors;
}

/**
 * A "New contact" form. Name and email are required; "Send me updates by email" is a single
 * Checkbox, saved with the form. Errors follow Patterns / Forms and Validation: checked on submit,
 * all shown at once in a summary that takes focus and links to each field, then each field's error
 * follows its value so it clears as soon as it's fixed.
 */
export function NewContactForm({ onSave, onCancel }: NewContactFormProps) {
  const prefix = React.useId();
  const ids: Record<FieldKey, string> = { name: `${prefix}-name`, email: `${prefix}-email` };
  const [values, setValues] = React.useState<NewContact>(EMPTY);
  const [submitted, setSubmitted] = React.useState(false);
  const [attempt, setAttempt] = React.useState(0);
  // What the summary lists: the errors as of the last submit. It's a live region, so it doesn't
  // change while people type; the fields do.
  const [summaryErrors, setSummaryErrors] = React.useState<FieldError[]>([]);
  const [saving, setSaving] = React.useState(false);
  const summary = React.useRef<HTMLDivElement>(null);

  const errors = submitted ? check(values) : [];
  const errorFor = (key: FieldKey) => errors.find((error) => error.key === key)?.message;

  // Move focus to the summary after each failed submit, so it's read out and people start there.
  React.useEffect(() => {
    if (attempt > 0) summary.current?.focus();
  }, [attempt]);

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (saving) return;
    setSubmitted(true);
    const failed = check(values);
    setSummaryErrors(failed);
    if (failed.length > 0) {
      setAttempt((count) => count + 1);
      return;
    }
    setSaving(true);
    try {
      await onSave({ ...values, name: values.name.trim(), email: values.email.trim() });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Form title="New contact" requiredLegend noValidate onSubmit={submit}>
      {summaryErrors.length > 0 ? (
        <FormSection>
          <SectionMessage
            ref={summary}
            tabIndex={-1}
            tone="error"
            title={`Fix ${summaryErrors.length === 1 ? '1 field' : `${summaryErrors.length} fields`} to save the contact`}
            errors={summaryErrors.map(({ key, label, message }) => ({ label, message, targetId: ids[key] }))}
          />
        </FormSection>
      ) : null}
      <FormSection>
        <Field label="Name" required state={errorFor('name') ? 'error' : 'default'} message={errorFor('name')}>
          <TextField
            id={ids.name}
            name="name"
            autoComplete="name"
            invalid={Boolean(errorFor('name'))}
            value={values.name}
            onChange={(event) => setValues((current) => ({ ...current, name: event.target.value }))}
          />
        </Field>
        <Field label="Email" required state={errorFor('email') ? 'error' : 'default'} message={errorFor('email')}>
          <TextField
            id={ids.email}
            name="email"
            type="email"
            autoComplete="email"
            invalid={Boolean(errorFor('email'))}
            value={values.email}
            onChange={(event) => setValues((current) => ({ ...current, email: event.target.value }))}
          />
        </Field>
        <Checkbox
          name="emailUpdates"
          label="Send me updates by email"
          checked={values.emailUpdates}
          onCheckedChange={(checked) => setValues((current) => ({ ...current, emailUpdates: checked }))}
        />
      </FormSection>
      <FormFooter>
        {onCancel ? (
          <Button prominence="tertiary" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
        <Button prominence="primary" type="submit" isLoading={saving}>
          Save
        </Button>
      </FormFooter>
    </Form>
  );
}

